{
  "candidate_claims": [
    {
      "claim": "GitHub Agentic Workflows (gh-aw) Markdown files combine natural-language instructions with structured YAML frontmatter configuration, compiling into executable GitHub Actions workflows for recurring repository automation.",
      "evidence_refs": [
        {
          "page": 2,
          "quote": "In a gh-aw workflow, the source artifact is not a conventional hand-written Actions YAML file. Instead, developers write a Markdown file, typically under .github/workflows/, that combines structured configuration with natural-language instructions for an AI agent. The gh-aw compiler then turns the Markdown source into a generated Actions workflow that can be triggered by standard GitHub events, schedules, or manual dispatches."
        }
      ],
      "importance": "load_bearing"
    },
    {
      "claim": "gh-aw workflows contain substantial instructions with a median of 556.5 words per file and are organized with a median of 9 headings per file, falling into the difficult reading range with a median Flesch Reading Ease score of 38.8.",
      "evidence_refs": [
        {
          "page": 5,
          "quote": "Finding #1: gh-aw Markdown files contain a median of 9 headings per file, with “step,” “phase,” and “issue” as the most frequent heading words."
        },
        {
          "page": 5,
          "quote": "Finding #2: gh-aw Markdown files fall within the conventional difficult range to read, with a median Flesch Reading Ease score of 38.8."
        }
      ],
      "importance": "supporting"
    },
    {
      "claim": "Total Markdown size grows significantly during the first 4 months at the project level, and a median of 74.5% of Markdown maintenance changes touch the frontmatter compared with 50.0% touching the body.",
      "evidence_refs": [
        {
          "page": 6,
          "quote": "Finding #3: Gh-aw total Markdown size grows significantly during the first 4 months at the project level"
        },
        {
          "page": 6,
          "quote": "Finding #4: At project level, a median of 74.5% of Markdown maintenance changes touch frontmatter, compared with 50.0% touching the body."
        }
      ],
      "importance": "supporting"
    },
    {
      "claim": "The instruction taxonomy identifies ten categories, where Tasks (97.6%), Outputs (95.8%), Constraints (93.8%), and Processes (93.4%) are the most common, while Safety (25.0%) and Communication (63.9%) are less frequent.",
      "evidence_refs": [
        {
          "page": 7,
          "quote": "Finding #5: Tasks, outputs, constraints, and execution processes are common elements of gh-aw Markdown, each appearing in at least 93.4% of labeled files."
        }
      ],
      "importance": "load_bearing"
    },
    {
      "claim": "One-shot Gemini achieves the highest performance for LLM-based instruction classification with an F1 score of 0.818, 86.81% subcategory agreement, and Cohen's kappa of 0.715.",
      "evidence_refs": [
        {
          "page": 12,
          "quote": "Finding #6: One-shot Gemini reaches the highest observed F1 (0.818), with 86.81% subcategory agreement and Cohen’s κ = 0.715."
        }
      ],
      "importance": "supporting"
    }
  ],
  "key_claims": [
    "GitHub Agentic Workflows (gh-aw) use Markdown files combining YAML frontmatter configuration and prose instructions to automate recurring repository tasks via AI agents.",
    "Among analyzed repositories, nearly 30% reference external Markdown sources, making cross-project workflow updates behave like evolving software dependencies.",
    "An empirical instruction taxonomy reveals that tasks, outputs, constraints, and processes appear in over 93% of workflows, whereas safety instructions and resource budgets are significantly less common.",
    "LLMs (such as Gemini 3.1 Pro) can automatically classify instruction types with high accuracy (F1 score of 0.818)."
  ],
  "limitations": [
    "The corpus is constrained by GitHub's search API limits, and findings primarily generalize to repositories with 10 or more GitHub stars.",
    "Readability metrics (FRE) and automated classifications are evaluated on complete Markdown files containing code blocks and syntax, which may affect score interpretations.",
    "Taxonomy coding and LLM classification assess explicit textual support rather than measuring whether specific instruction types directly improve agent execution success or runtime outcomes."
  ],
